const d=$input.first().json;
const now=new Date(); const ist=new Date(now.toLocaleString("en-US",{timeZone:"Asia/Kolkata"}));
const wd=ist.getDay(); const mins=ist.getHours()*60+ist.getMinutes(); const key=ist.getFullYear()+"-"+String(ist.getMonth()+1).padStart(2,"0")+"-"+String(ist.getDate()).padStart(2,"0"); const holidays=new Set(["2026-01-15","2026-01-26","2026-03-03","2026-03-26","2026-03-31","2026-04-03","2026-04-14","2026-05-01","2026-05-28","2026-06-26","2026-09-14","2026-10-02","2026-10-20","2026-11-10","2026-11-24","2026-12-25"]); const clock=holidays.has(key)?"HOLIDAY":(wd===0||wd===6)?"WEEKEND":(mins<555?"BEFORE_OPEN":(mins>940?"AFTER_CLOSE":"OPEN")); const market=clock==="OPEN";
const lineage=["with_runid","with_sha","with_writer","with_cycle","with_source_ts"].every(k=>Number(d[k])===219)
 && ["run_ids","git_shas","writer_ids","cycle_ids"].every(k=>Number(d[k])===1);
const universe=Number(d.total_rows)===219 && Number(d.unique_symbols)===219;
const fresh=market?(typeof d.source_age_seconds==="number" && d.source_age_seconds<=1200):"NOT_REQUIRED";
const ok=universe&&lineage&&(fresh===true||fresh==="NOT_REQUIRED");
return [{json:{status:ok?"PASS":"FAIL",total_rows:d.total_rows,unique_symbols:d.unique_symbols,
source_age_seconds:d.source_age_seconds,lineage_complete:lineage,fresh_during_market:fresh,
